interface Store { save(id: string): void; load(id: string): string }

class CountingStore implements Store {          // `implements` checks the shape only
  private count = 0;
  constructor(private readonly inner: Store) {}
  save(id: string): void { this.count++; this.inner.save(id); }   // hand-written forward
  load(id: string): string { return this.inner.load(id); }        // hand-written forward
}
